import assert from'node:assert/strict';import{createRequire}from'node:module';import{readFile,mkdir,writeFile}from'node:fs/promises';const r=createRequire(process.env.SDS_BROWSER_MODULES+'/package.json'),b=await r('puppeteer-core').launch({executablePath:'/usr/local/bin/google-chrome',headless:true,args:['--no-sandbox']});const out=process.env.SDS_FREE_OUT||'/tmp/sds-free-actions';await mkdir(out,{recursive:true});const axe=await readFile(r.resolve('axe-core/axe.min.js'),'utf8'),report={views:[],paid:false,paymentSent:false};async function shot(p,name,width,theme){await p.addScriptTag({content:axe});const result=await p.evaluate(async()=>{let a=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa']}});return{axe:a.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),width:innerWidth,scrollWidth:document.documentElement.scrollWidth};});const screenshot=name+'-'+width+'-'+theme+'.jpg';await p.screenshot({path:out+'/'+screenshot,fullPage:true,type:'jpeg',quality:72});report.views.push({name,width,theme,screenshot,...result});await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
try{for(const width of[390,768,1440])for(const theme of['drafting','dark']){const c=await b.createBrowserContext(),p=await c.newPage();await p.setViewport({width,height:900});await p.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await p.evaluateOnNewDocument(t=>localStorage.setItem('sdd-theme',t),theme);await p.goto('http://127.0.0.1:31861/',{waitUntil:'networkidle2'});await p.locator('form input').fill('https://example.com');await p.locator('form button[type=submit]').click();await p.waitForSelector('section[aria-label="Your free check"]');assert.match(await p.$eval('section[aria-label="Your free check"]',e=>e.textContent),/249 USD|349 USD/);await p.waitForFunction(()=>!document.querySelector('form button[type=submit]')?.disabled);await shot(p,'hero-real-check',width,theme);if(await p.$('section[aria-label="Your free check"] a[href="/tools/ai-readiness"]')){await p.locator('section[aria-label="Your free check"] a[href="/tools/ai-readiness"]').click();await p.waitForSelector('[data-grade]');assert.match(await p.$eval('input[aria-label="Website URL"]',e=>e.value),/example.com/);await shot(p,'hero-every-check-keeps-result',width,theme);}await p.goto('http://127.0.0.1:31861/tools/ai-readiness',{waitUntil:'networkidle2'});await p.locator('input[aria-label="Website URL"]').fill('https://example.com');await p.locator('form button').click();await p.waitForSelector('[data-grade]');await shot(p,'readiness-real-result',width,theme);await p.locator('input[aria-label="Website URL"]').fill('http://127.0.0.1/');await p.locator('form button').click();await p.waitForSelector('[role=alert]');await shot(p,'readiness-private-target-refusal',width,theme);await p.goto('http://127.0.0.1:31861/x402',{waitUntil:'networkidle2'});await p.locator('section[aria-labelledby=quote-title] button').click();await p.waitForFunction(()=>document.querySelector('section[aria-labelledby=quote-title]').textContent.includes('HTTP 402')||document.querySelector('section[aria-labelledby=quote-title]').textContent.includes('did not answer'));await shot(p,'actual-unpaid-gateway-quote',width,theme);await c.close();console.log('FREE',width,theme)}}finally{await b.close();await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
